The FileInputStream class in Java is used to read data from a file in the form of bytes. It’s ideal for reading binary data such as images or audio files. For reading text files, it’s better to use FileReader.Direct Access: It directly reads the file content from the disk without bufferingPlatform Independent: It can work on any operating systemDeclarationThe FileInputStream class extends the InputStream class, which means it inherits methods for reading raw byte data from files.public class FileInputStream extends InputStreamExample: FileInputStream class to read data from file.
            Java

    import java.io.*;

public class Geeks{

    public static void main(String[] args){

        // Use try-with-resources to automatically close the
        // stream
        try (FileInputStream fi
             = new FileInputStream("file1.txt")) {

            // Display file channel information
            System.out.println("Channel: "
                               + fi.getChannel());

            // Display file descriptor
            System.out.println("File Descriptor: "
                               + fi.getFD());

            // Show available bytes in the stream
            System.out.println("Number of remaining bytes: "
                               + fi.available());

            // Skip first few bytes
            fi.skip(4);

            System.out.println("File Contents:");

            // Read and print file content
            int ch;
            while ((ch = fi.read()) != -1) {
                System.out.print((char)ch);
            }
        }
        catch (FileNotFoundException e) {
            System.out.println(
                "File not found: Ensure 'file1.txt' exists in the working directory.");
        }
        catch (IOException e) {
            System.out.println(
                "An error occurred while reading the file: "
                + e.getMessage());
        }
    }
}

